const payload = $input.first().json.body ?? $input.first().json;
const recipients = payload.recipients?.whatsapp ?? [];
const santri = payload.santri ?? {};
const group = payload.group ?? {};
const ringkasan = payload.ringkasan?.baris ?? {};
const event = payload.event ?? 'pendaftaran_baru';
const isStatusUpdate = event === 'status_verifikasi_diperbarui';

function normalizePhone(phone) {
  const raw = String(phone ?? '').replace(/[^0-9]/g, '');
  if (raw.startsWith('08')) return '62' + raw.slice(1);
  if (raw.startsWith('8')) return '62' + raw;
  return raw;
}

function roleLabel(role) {
  if (role === 'ibu') return 'Ibu';
  if (role === 'wali') return 'Bapak/Ibu Wali';
  return 'Bapak';
}

const summaryText = Object.entries(ringkasan)
  .map(([label, value]) => `- ${label}: ${value ?? '-'}`)
  .join('\n');

return recipients.map((recipient) => {
  const kelasLabel = group.kelas === 'ikhwan' ? 'ikhwan (putra)' : 'akhwat (putri)';
  const greeting = `${roleLabel(recipient.role)} ${recipient.name ?? ''}`.trim();
  const message = isStatusUpdate
    ? `Assalamu'alaikum ${greeting},\n\nStatus verifikasi data SPSB untuk ananda *${santri.nama_lengkap ?? '-'}* telah diperbarui oleh panitia.\n\n*Status terbaru:* ${santri.status_label ?? '-'}\n${santri.pesan_status ?? ''}\n\n*Ringkasan:*\n${summaryText}\n\nCek status pendataan:\n${payload.links?.cek_status ?? '-'}\n\nJazakumullah khairan.\nPanitia SPSB`
    : `Assalamu'alaikum ${greeting},\n\nAlhamdulillah, data pendataan SPSB untuk ananda *${santri.nama_lengkap ?? '-'}* sudah masuk dan diterima oleh sistem.\n\n*Ringkasan data:*\n${summaryText}\n\n*Informasi grup kelas ${kelasLabel}:*\n${group.aturan ?? '-'}\n${group.link ? `Link grup: ${group.link}` : 'Link grup belum tersedia. Admin akan mengirimkan link menyusul.'}\n\nTautan cetak bukti pendataan:\n${payload.links?.cetak ?? '-'}\n\nJazakumullah khairan.\nPanitia SPSB`;

  return {
    json: {
      phone: normalizePhone(recipient.phone),
      role: recipient.role,
      name: recipient.name,
      event,
      message,
      payload
    }
  };
});
